// Deterministic checks the AI must not be trusted with. `query` holds the tool inputs.
const q = typeof query === 'string' ? JSON.parse(query) : query;
const errors = [];
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
const now = new Date().toLocaleTimeString('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit' });
const date = String(q.date || '').trim();
const time = String(q.time || '').trim();
const phone = String(q.phone || '').replace(/[\s-]/g, '').replace(/^(\+20|0020|20)(?=1)/, '0');

if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) errors.push('date must be YYYY-MM-DD');
if (!/^\d{2}:\d{2}$/.test(time)) errors.push('time must be HH:mm (24-hour)');
if (!/^01[0125]\d{8}$/.test(phone)) errors.push('phone must be an Egyptian mobile like 01012345678');

if (!errors.length) {
  const day = new Date(date + 'T12:00:00Z');
  const days = Math.round((day - new Date(today + 'T12:00:00Z')) / 864e5);
  const [h, m] = time.split(':').map(Number);
  if (days < 0 || (days === 0 && time <= now)) errors.push('that time is in the past');
  if (days > 60) errors.push('bookings are open up to 60 days ahead');
  if (day.getUTCDay() === 5) errors.push('the clinic is closed on Friday');
  if (h < 10 || h > 21 || (h === 21 && m > 30)) errors.push('appointments run from 10:00 to 21:30');
  if (m !== 0 && m !== 30) errors.push('appointments start on the hour or half hour');
}
return errors.length
  ? 'NOT VALID: ' + errors.join('; ')
  : `VALID: date ${date}, time ${time}, phone ${phone}. Now check Read Appointments for this date.`;

// "/reply T-261030-AB12 your message" (also "/reply@BotName ...") from the staff group.
const m = $json.message;
const match = (m.text || '').match(/^\/reply(?:@\w+)?\s+(T-[\w-]+)\s+([\s\S]+)/i);
return [{ json: {
  valid: !!match,
  ticket_id: match ? match[1].toUpperCase() : '',
  reply: match ? match[2].trim() : '',
  staff_chat_id: m.chat.id,
  staff_message_id: m.message_id,
  staff_name: m.from?.username ? '@' + m.from.username : (m.from?.first_name || 'staff'),
} }];

// The Drive node exported the Google Doc as plain text into a binary file. Read it as a string.
// Refuse to wipe a working knowledge base with an empty or broken document.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const content = buffer.toString('utf8').replace(/^\uFEFF/, '');
if (content.trim().length < 200) throw new Error(`KB document looks empty (${content.length} chars). Store not updated.`);
return [{ json: { content, chars: content.length, loaded_at: $now.toISO() } }];
